12	import { readFileSync } from "node:fs";
13	import { join } from "node:path";
14	import { FailureCode } from "../types.ts";
15	
16	/** Heading of the section this module appends. */
17	export const ADDED_SECTION = "## Added by Roster";
18	
19	const LIB_PATH = join(import.meta.dir, "rules-lib.md");
20	const KNOWN_CODES: ReadonlySet<string> = new Set(Object.values(FailureCode));
21	const ROW = /^\|\s*([A-Z][0-9]+)\s*\|\s*(\S.*?)\s*\|\s*$/;
22	
23	export interface AddedRule {
24	  rule: string;
25	  answers: FailureCode[];
26	}
27	
28	export interface RulesCandidate {
29	  rules: string;
30	  added: AddedRule[];
31	}
