33	/**
34	 * Code-to-rule mapping, read from ./rules-lib.md. Rows whose code is not in the `FailureCode` enum are
35	 * ignored, so a typo in the table drops a rule rather than inventing a code.
36	 */
37	export function loadRulesLib(path: string = LIB_PATH): Map<FailureCode, string> {
38	  const lib = new Map<FailureCode, string>();
39	  for (const line of readFileSync(path, "utf8").split("\n")) {
40	    const row = ROW.exec(line);
41	    if (!row) continue;
42	    const code = row[1]!;
43	    if (!KNOWN_CODES.has(code)) continue;
44	    lib.set(code as FailureCode, row[2]!);
45	  }
46	  return lib;
47	}
48	
49	/**
50	 * Base rules plus one appended rule per distinct failure code that the library maps. Returns the base text
51	 * untouched when nothing can be added.
52	 */
53	export function proposeRulesCandidate(baseRules: string, codes: FailureCode[]): RulesCandidate {
54	  const lib = loadRulesLib();
55	  const base = baseRules.toLowerCase();
56	  const seen = new Set<FailureCode>();
57	  const order: string[] = [];
58	  const answers = new Map<string, FailureCode[]>();
59	
60	  for (const code of codes) {
61	    if (seen.has(code)) continue;
62	    seen.add(code);
63	    const rule = lib.get(code);
64	    if (rule === undefined || base.includes(rule.toLowerCase())) continue;
65	    const cited = answers.get(rule);
66	    if (cited) cited.push(code);
67	    else {
68	      answers.set(rule, [code]);
69	      order.push(rule);
70	    }
71	  }
72	
73	  if (order.length === 0) return { rules: baseRules, added: [] };
74	
75	  const bullets = order.map((rule) => `- ${rule} (answers ${answers.get(rule)!.join(", ")})`);
76	  const gap = baseRules === "" || baseRules.endsWith("\n\n") ? "" : baseRules.endsWith("\n") ? "\n" : "\n\n";
77	  return {
78	    rules: `${baseRules}${gap}${ADDED_SECTION}\n\n${bullets.join("\n")}\n`,
79	    added: order.map((rule) => ({ rule, answers: answers.get(rule)! })),
80	  };
81	}
